// ─────────────────────────────────────────────────────────────────────────────
// Server-side API — generated by Backplane for {{PROJECT_NAME}}
//
// Your app talks to Supabase directly (row-level security protects every
// table). This Worker does what must happen on a server: billing checkout and
// portal, verified Stripe webhooks that keep subscription status in the
// database, template-specific jobs (newsletter confirmation, webhook relay,
// booking reminders) and Backplane's health probes.
//
// Backplane tracks this file; edits are marked USER MODIFIED and never
// overwritten without asking.
// ─────────────────────────────────────────────────────────────────────────────

const STRIPE_VERSION = "2026-08-26.dahlia";
const JSON_HEADERS = { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" };

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const origin = request.headers.get("Origin");
    try {
      if (request.method === "OPTIONS") return preflight(env, origin);
      const path = url.pathname.replace(/\/+$/, "") || "/";
      if (path === "/") return json({ service: env.WORKER_NAME || "api", ok: true });
      if (path === "/__backplane/health") return await health(request, env, url);
      if (path.startsWith("/__backplane/probe/stripe/")) return await probeStripe(request, env, path.split("/").pop());
      if (path === "/stripe/webhook" && request.method === "POST") return await stripeWebhook(request, env, ctx);
      if (path === "/billing/checkout" && request.method === "POST") return cors(await billingCheckout(request, env), env, origin);
      if (path === "/billing/portal" && request.method === "POST") return cors(await billingPortal(request, env), env, origin);
      if (env.TEMPLATE === "newsletter" && path === "/subscribe" && request.method === "POST") return cors(await subscribe(request, env, url), env, origin);
      if (env.TEMPLATE === "newsletter" && path === "/confirm" && request.method === "GET") return await confirm(url, env);
      if (env.TEMPLATE === "webhook-relay" && path.startsWith("/hooks/") && request.method === "POST") return await relay(request, env, ctx, path.split("/")[2]);
      return json({ error: "not found" }, 404);
    } catch (err) {
      console.error("Unhandled error", request.method, url.pathname, err && err.stack || err);
      ctx.waitUntil(logEvent(env, "worker", "error", `${request.method} ${url.pathname}: ${String(err && err.message || err)}`));
      return json({ error: "internal error" }, 500);
    }
  },
  async scheduled(event, env, ctx) {
    if (env.TEMPLATE === "booking") ctx.waitUntil(bookingReminders(env));
    ctx.waitUntil(housekeeping(env));
  },
};

function json(body, status = 200, extra = {}) {
  return new Response(JSON.stringify(body), { status, headers: { ...JSON_HEADERS, ...extra } });
}
function preflight(env, origin) {
  if (!origin || origin !== env.APP_URL) return new Response(null, { status: 204 });
  return new Response(null, { status: 204, headers: { "Access-Control-Allow-Origin": origin, "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization", "Access-Control-Max-Age": "86400", Vary: "Origin" } });
}
function cors(resp, env, origin) {
  if (!origin || origin !== env.APP_URL) return resp;
  const r = new Response(resp.body, resp);
  r.headers.set("Access-Control-Allow-Origin", origin);
  r.headers.set("Vary", "Origin");
  return r;
}

const enc = new TextEncoder();
async function hmacHex(secret, data) {
  const key = await crypto.subtle.importKey("raw", enc.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return [...new Uint8Array(await crypto.subtle.sign("HMAC", key, enc.encode(data)))].map((b) => b.toString(16).padStart(2, "0")).join("");
}
function safeEqual(a, b) {
  if (typeof a !== "string" || typeof b !== "string" || a.length !== b.length) return false;
  let d = 0;
  for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return d === 0;
}
function bearer(request) {
  const h = request.headers.get("Authorization") || "";
  return h.startsWith("Bearer ") ? h.slice(7) : "";
}

// ───────── Supabase ─────────
function sbHeaders(env, extra = {}) {
  const key = env.SUPABASE_SECRET_KEY || "";
  const h = { apikey: key, "Content-Type": "application/json", ...extra };
  if (key.startsWith("eyJ")) h.Authorization = `Bearer ${key}`;
  return h;
}
async function sb(env, method, path, body, prefer) {
  const res = await fetch(`${env.SUPABASE_URL}/rest/v1/${path}`, { method, headers: sbHeaders(env, prefer ? { Prefer: prefer } : {}), body: body === undefined ? undefined : JSON.stringify(body) });
  const text = await res.text();
  if (!res.ok) throw new Error(`Supabase ${method} ${path.split("?")[0]} → ${res.status}: ${text.slice(0, 300)}`);
  return text ? JSON.parse(text) : null;
}
// Resolves the signed-in user from their Supabase access token.
async function currentUser(request, env) {
  const token = bearer(request);
  if (!token) return null;
  const res = await fetch(`${env.SUPABASE_URL}/auth/v1/user`, { headers: { apikey: env.SUPABASE_SECRET_KEY, Authorization: `Bearer ${token}` } });
  if (!res.ok) return null;
  return res.json();
}
async function logEvent(env, source, kind, message, ref = null, isProbe = false) {
  try {
    await sb(env, "POST", "bp_events", [{ source, kind, message: String(message).slice(0, 500), ref, is_probe: isProbe }], "return=minimal");
  } catch (e) {
    console.warn("bp_events write failed", String(e));
  }
}

// ───────── Stripe ─────────
function form(obj, prefix = "", out = new URLSearchParams()) {
  for (const [k, v] of Object.entries(obj)) {
    const key = prefix ? `${prefix}[${k}]` : k;
    if (v === undefined || v === null) continue;
    if (Array.isArray(v)) v.forEach((x, i) => (typeof x === "object" ? form(x, `${key}[${i}]`, out) : out.append(`${key}[]`, String(x))));
    else if (typeof v === "object") form(v, key, out);
    else out.append(key, String(v));
  }
  return out;
}
async function stripe(env, method, path, params) {
  const res = await fetch(`${env.STRIPE_API_BASE || "https://api.stripe.com"}${path}`, {
    method, headers: { Authorization: `Bearer ${env.STRIPE_SECRET_KEY}`, "Stripe-Version": STRIPE_VERSION, "Content-Type": "application/x-www-form-urlencoded" },
    body: params ? form(params).toString() : undefined,
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(`Stripe ${path} → ${res.status}: ${data?.error?.message || "error"}`);
  return data;
}
async function verifyStripe(payload, header, secret) {
  if (!header || !secret) return false;
  let t = null;
  const sigs = [];
  for (const part of header.split(",")) {
    const [k, v] = part.trim().split("=");
    if (k === "t") t = v;
    else if (k === "v1" && v) sigs.push(v);
  }
  if (!t || !sigs.length || Math.abs(Date.now() / 1000 - Number(t)) > 300) return false;
  const expected = await hmacHex(secret, `${t}.${payload}`);
  return sigs.some((s) => safeEqual(s, expected));
}

async function billingCheckout(request, env) {
  if (!env.STRIPE_SECRET_KEY || !env.PRICE_ID) return json({ error: "billing is not configured" }, 501);
  const user = await currentUser(request, env);
  if (!user) return json({ error: "sign in first" }, 401);
  const subscription = env.BILLING_MODE === "subscription";
  const session = await stripe(env, "POST", "/v1/checkout/sessions", {
    mode: subscription ? "subscription" : "payment",
    line_items: [{ price: env.PRICE_ID, quantity: 1 }],
    client_reference_id: user.id,
    customer_email: user.email,
    success_url: `${env.APP_URL || ""}/billing/success?session_id={CHECKOUT_SESSION_ID}`,
    cancel_url: env.APP_URL || undefined,
    metadata: { user_id: user.id },
    subscription_data: subscription ? { metadata: { user_id: user.id } } : undefined,
  });
  return json({ id: session.id, url: session.url });
}

async function billingPortal(request, env) {
  const user = await currentUser(request, env);
  if (!user) return json({ error: "sign in first" }, 401);
  const rows = await sb(env, "GET", `subscriptions?owner_id=eq.${user.id}&select=stripe_customer_id&order=created_at.desc&limit=1`);
  const customer = rows?.[0]?.stripe_customer_id;
  if (!customer) return json({ error: "no subscription yet" }, 404);
  const portal = await stripe(env, "POST", "/v1/billing_portal/sessions", { customer, return_url: env.APP_URL || undefined });
  return json({ url: portal.url });
}

async function stripeWebhook(request, env, ctx) {
  const payload = await request.text();
  if (!(await verifyStripe(payload, request.headers.get("Stripe-Signature"), env.STRIPE_WEBHOOK_SECRET))) return json({ error: "invalid signature" }, 400);
  const event = JSON.parse(payload);
  const obj = event.data?.object || {};
  if (event.type === "checkout.session.expired") {
    if (obj.metadata?.backplane_probe === "1" && env.PROBES) await env.PROBES.put(`probe:cs:${obj.id}`, JSON.stringify({ event_id: event.id, at: new Date().toISOString() }), { expirationTtl: 3600 });
    return json({ received: true, type: event.type });
  }
  if (event.type.startsWith("customer.subscription.")) {
    const userId = obj.metadata?.user_id;
    if (userId) {
      await sb(env, "POST", "subscriptions?on_conflict=stripe_subscription_id", [{
        owner_id: userId, stripe_customer_id: obj.customer, stripe_subscription_id: obj.id,
        status: event.type === "customer.subscription.deleted" ? "canceled" : obj.status,
        price_id: obj.items?.data?.[0]?.price?.id ?? null,
        current_period_end: obj.items?.data?.[0]?.current_period_end ? new Date(obj.items.data[0].current_period_end * 1000).toISOString() : null,
      }], "resolution=merge-duplicates,return=minimal");
      ctx.waitUntil(logEvent(env, "stripe", "subscription", `Subscription ${obj.id} is ${obj.status}`, obj.id, event.livemode === false && obj.metadata?.backplane_probe === "1"));
    }
    return json({ received: true, type: event.type });
  }
  if (event.type === "checkout.session.completed" && obj.metadata?.row_table && obj.metadata?.row_id) {
    const allowed = String(env.PAYABLE_TABLES || "bookings,orders,purchases").split(",");
    if (allowed.includes(obj.metadata.row_table)) {
      await sb(env, "PATCH", `${obj.metadata.row_table}?id=eq.${obj.metadata.row_id}`, { paid: true, stripe_session_id: obj.id }, "return=minimal");
      ctx.waitUntil(logEvent(env, "stripe", "payment", `Payment for ${obj.metadata.row_table} ${obj.metadata.row_id}`, obj.id));
    }
  }
  return json({ received: true, type: event.type });
}

// ───────── Newsletter (double opt-in) ─────────
async function subscribe(request, env, url) {
  const { email } = await request.json().catch(() => ({}));
  if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return json({ error: "Enter a valid email." }, 400);
  const token = crypto.randomUUID() + crypto.randomUUID();
  await sb(env, "POST", "subscribers?on_conflict=email", [{ email: email.toLowerCase(), status: "pending", confirm_token_hash: await hmacHex(env.SIGNING_SECRET, token) }], "resolution=merge-duplicates,return=minimal");
  const link = `${url.protocol}//${url.host}/confirm?t=${token}`;
  if (env.RESEND_API_KEY) {
    await fetch("https://api.resend.com/emails", { method: "POST", headers: { Authorization: `Bearer ${env.RESEND_API_KEY}`, "Content-Type": "application/json" },
      body: JSON.stringify({ from: env.FROM_EMAIL, to: [email], subject: `Confirm your subscription to ${env.BUSINESS_NAME || "our newsletter"}`,
        html: `<p>Tap to confirm your subscription:</p><p><a href="${link}">Confirm subscription</a></p><p>If you didn't sign up, ignore this email.</p>` }) });
  }
  return json({ ok: true });
}
async function confirm(url, env) {
  const token = url.searchParams.get("t") || "";
  const hash = await hmacHex(env.SIGNING_SECRET, token);
  const rows = await sb(env, "PATCH", `subscribers?confirm_token_hash=eq.${hash}&status=eq.pending`, { status: "confirmed", confirmed_at: new Date().toISOString(), confirm_token_hash: null }, "return=representation");
  const ok = rows?.length > 0;
  return new Response(`<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Subscription</title><body style="font:17px/1.6 system-ui;display:grid;place-items:center;min-height:90vh"><p>${ok ? "You're subscribed. Thank you!" : "This link was already used or has expired."}</p></body>`,
    { status: ok ? 200 : 410, headers: { "content-type": "text/html; charset=utf-8" } });
}

// ───────── Webhook relay ─────────
async function relay(request, env, ctx, sourceId) {
  if (!/^[0-9a-f-]{36}$/.test(sourceId || "")) return json({ error: "unknown source" }, 404);
  const rows = await sb(env, "GET", `sources?id=eq.${sourceId}&select=id,owner_id,signing_secret,forward_url`);
  const src = rows?.[0];
  if (!src) return json({ error: "unknown source" }, 404);
  const payload = await request.text();
  const header = request.headers.get("X-Signature") || (request.headers.get("X-Hub-Signature-256") || "").replace(/^sha256=/, "");
  const verified = header ? safeEqual(header, await hmacHex(src.signing_secret, payload)) : false;
  if (!verified) return json({ error: "invalid signature" }, 401);
  let parsed;
  try { parsed = JSON.parse(payload); } catch { parsed = { raw: payload }; }
  const [delivery] = await sb(env, "POST", "deliveries", [{ owner_id: src.owner_id, source_id: src.id, payload: parsed, verified: true }], "return=representation").catch(() => [null]);
  if (src.forward_url && delivery) {
    ctx.waitUntil((async () => {
      let status = 0;
      try {
        const r = await fetch(src.forward_url, { method: "POST", headers: { "Content-Type": "application/json" }, body: payload, signal: AbortSignal.timeout(10000) });
        status = r.status;
      } catch { status = 599; }
      await sb(env, "PATCH", `deliveries?id=eq.${delivery.id}`, { forwarded_status: status, forwarded_at: new Date().toISOString() }, "return=minimal").catch(() => {});
    })());
  }
  return json({ received: true });
}

// ───────── Booking reminders ─────────
async function bookingReminders(env) {
  if (!env.RESEND_API_KEY) return;
  const from = new Date(Date.now() + 23 * 3600e3).toISOString();
  const to = new Date(Date.now() + 25 * 3600e3).toISOString();
  const due = await sb(env, "GET", `bookings?status=eq.confirmed&reminder_sent_at=is.null&starts_at=gte.${from}&starts_at=lte.${to}&select=id,email,starts_at&limit=50`).catch(() => []);
  for (const b of due || []) {
    if (!b.email) continue;
    const r = await fetch("https://api.resend.com/emails", { method: "POST", headers: { Authorization: `Bearer ${env.RESEND_API_KEY}`, "Content-Type": "application/json" },
      body: JSON.stringify({ from: env.FROM_EMAIL, to: [b.email], subject: "Reminder: your appointment tomorrow", html: `<p>This is a reminder of your appointment on ${new Date(b.starts_at).toUTCString()}.</p>` }) });
    if (r.ok) await sb(env, "PATCH", `bookings?id=eq.${b.id}`, { reminder_sent_at: new Date().toISOString() }, "return=minimal");
  }
}

async function housekeeping(env) {
  const dayAgo = new Date(Date.now() - 86400e3).toISOString();
  await sb(env, "DELETE", `backplane_probe?created_at=lt.${dayAgo}`, undefined, "return=minimal").catch(() => {});
  await sb(env, "DELETE", `bp_events?is_probe=eq.true&at=lt.${dayAgo}`, undefined, "return=minimal").catch(() => {});
}

// ───────── Backplane probes ─────────
async function timed(fn) {
  const t0 = Date.now();
  try {
    return { ok: true, ms: Date.now() - t0, detail: (await fn()) || "" };
  } catch (e) {
    return { ok: false, ms: Date.now() - t0, error: String(e.message || e) };
  }
}
async function health(request, env, url) {
  if (!env.BACKPLANE_PROBE_TOKEN || !safeEqual(bearer(request), env.BACKPLANE_PROBE_TOKEN)) return json({ error: "unauthorized" }, 401);
  const full = url.searchParams.get("mode") === "full";
  const required = ["SUPABASE_URL", "SUPABASE_SECRET_KEY", "BACKPLANE_PROBE_TOKEN", "SIGNING_SECRET"];
  const missing = required.filter((k) => !env[k]);
  const checks = {};
  checks.supabase = await timed(async () => {
    await sb(env, "GET", "backplane_probe?select=id&limit=1");
    return "database reachable with the server key";
  });
  checks.kv = await timed(async () => {
    if (!env.PROBES) throw new Error("KV binding PROBES is not bound");
    if (full) {
      const k = `bp:health:${crypto.randomUUID()}`;
      await env.PROBES.put(k, "ok", { expirationTtl: 60 });
      if ((await env.PROBES.get(k)) !== "ok") throw new Error("read-back mismatch");
    }
    return "namespace reachable";
  });
  if (env.STRIPE_SECRET_KEY) {
    checks.stripe = await timed(async () => {
      const price = await stripe(env, "GET", `/v1/prices/${env.PRICE_ID}`);
      if (!price.active) throw new Error(`price ${env.PRICE_ID} is inactive`);
      return `price active (${price.livemode ? "live" : "test"} mode)`;
    });
  }
  if (env.RESEND_API_KEY) {
    checks.resend = await timed(async () => {
      const r = await fetch("https://api.resend.com/domains", { headers: { Authorization: `Bearer ${env.RESEND_API_KEY}` } });
      const d = await r.json().catch(() => ({}));
      if (r.ok) return "key valid (full access — a send-only key is safer)";
      if (d?.name === "restricted_api_key") return "send-only key valid";
      throw new Error(`key rejected (${r.status} ${d?.name || ""})`);
    });
  }
  const ok = missing.length === 0 && Object.values(checks).every((c) => c.ok);
  return json({ ok, worker: env.WORKER_NAME, version: env.CODE_VERSION || "", checks, missing, time: new Date().toISOString() }, 200, { "X-Backplane-Worker": env.WORKER_NAME || "" });
}
async function probeStripe(request, env, id) {
  if (!env.BACKPLANE_PROBE_TOKEN || !safeEqual(bearer(request), env.BACKPLANE_PROBE_TOKEN)) return json({ error: "unauthorized" }, 401);
  const v = env.PROBES ? await env.PROBES.get(`probe:cs:${id}`) : null;
  return json(v ? { found: true, ...JSON.parse(v) } : { found: false });
}
